#include "basis_cylindrical_kernel.h"
#include <fstream>
#include <iostream>
#include <iomanip>
int main(){namespace bc=SlurryBasisCylindrical;using C=std::complex<double>;double mapping=0;for(int m=0;m<=5;++m){auto D=bc::cylindrical_to_cartesian(m,6);Eigen::Vector3cd f;f<<C(.31,-.21),C(-.43,.73),C(.19,.11);const Eigen::VectorXcd a=D*f;for(double p:{0.,.23,1.37,3.12,5.71}){Eigen::Matrix3d R;R<<std::cos(p),-std::sin(p),0,std::sin(p),std::cos(p),0,0,0,1;Eigen::Vector3cd v=a.head<3>();for(int k=1;k<=6;++k)v+=std::cos(k*p)*a.segment<3>(3*(2*k-1))+std::sin(k*p)*a.segment<3>(3*(2*k));mapping=std::max(mapping,(v-R.cast<C>()*f*std::exp(C(0.,m*p))).norm());}}Eigen::MatrixXd t(3,2),s(3,2);t<<0.,1.,3.,.95,9.95,.08;double mu[3]={-std::sqrt(.6),0.,std::sqrt(.6)};for(int i=0;i<3;++i){s(i,0)=std::sqrt(99.25)*std::sqrt(1-mu[i]*mu[i]);s(i,1)=.5*mu[i];}const auto a=bc::modal_kernel(t,s,4,2048),b=bc::modal_kernel(t,s,4,4096);double convergence=0;std::ofstream out("/tmp/cylindrical_kernel_values.txt");out<<std::setprecision(17);for(int m=0;m<=4;++m){convergence=std::max(convergence,(a[m]-b[m]).norm()/b[m].norm());for(int i=0;i<9;++i)for(int j=0;j<9;++j)out<<m<<' '<<i<<' '<<j<<' '<<b[m](i,j).real()<<' '<<b[m](i,j).imag()<<'\n';}std::cout<<std::setprecision(17)<<"mapping_max="<<mapping<<" quadrature2048vs4096="<<convergence<<'\n';return mapping<1e-12&&convergence<1e-6?0:1;}
